ee:message.ee:set-payload:
%dw 2.0
output application/json

// Read valid and rejected records
var validRecords = payload.validRecords default []
var rejectedRecords = payload.rejectedRecords default []

// Calculate counts
var totalValid = sizeOf(validRecords)
var totalRejected = sizeOf(rejectedRecords)
var totalRecords = totalValid + totalRejected

// Read configured threshold
var threshold = vars.rejectionThreshold

// Calculate rejection percentage
var rejectionPercentage =
    if (totalRecords == 0)
        0
    else
        round(((totalRejected / totalRecords) * 100) * 100) / 100

// Compare percentage with threshold
var shouldAbort =
    rejectionPercentage > threshold

---
{
    totalRecords: totalRecords,
    totalValid: totalValid,
    totalRejected: totalRejected,

    rejectionPercentage: rejectionPercentage,
    configuredThreshold: threshold,

    processingDecision:
        if (shouldAbort)
            "ABORT"
        else
            "CONTINUE",

    persistenceAllowed: !shouldAbort,

    message:
        if (shouldAbort)
            "Rejection percentage exceeds the configured threshold. Import processing must be aborted before database persistence."
        else
            "Rejection percentage is within the configured threshold. Processing can continue to database persistence.",

    validRecords: validRecords,
    rejectedRecords: rejectedRecords
}
